7	import {
8	  diag,
9	  SpanStatusCode,
10	  trace,
11	  type AttributeValue,
12	  type SpanOptions,
13	} from '@opentelemetry/api';
14	import { safeJsonStringify } from '../utils/safeJsonStringify.js';
15	import {
16	  type GeminiCliOperation,
17	  GEN_AI_AGENT_DESCRIPTION,
18	  GEN_AI_AGENT_NAME,
19	  GEN_AI_CONVERSATION_ID,
20	  GEN_AI_INPUT_MESSAGES,
21	  GEN_AI_OPERATION_NAME,
22	  GEN_AI_OUTPUT_MESSAGES,
23	  SERVICE_DESCRIPTION,
24	  SERVICE_NAME,
25	} from './constants.js';
26	import { sessionId } from '../utils/session.js';
27	
28	const TRACER_NAME = 'gemini-cli';
29	const TRACER_VERSION = 'v1';
30	
31	/**
32	 * Metadata for a span.
33	 */
34	export interface SpanMetadata {
35	  /** The name of the span. */
36	  name: string;
37	  /** The input to the span. */
38	  input?: unknown;
39	  /** The output of the span. */
40	  output?: unknown;
41	  error?: unknown;
42	  /** Additional attributes for the span. */
43	  attributes: Record<string, AttributeValue>;
44	}
45	
46	/**
47	 * Runs a function in a new OpenTelemetry span.
48	 *
49	 * The `meta` object will be automatically used to set the span's status and attributes upon completion.
50	 *
51	 * @example
52	 * ```typescript
53	 * runInDevTraceSpan({ name: 'my-operation' }, ({ metadata }) => {
54	 *   metadata.input = { foo: 'bar' };
55	 *   // ... do work ...
56	 *   metadata.output = { result: 'baz' };
57	 *   metadata.attributes['my.custom.attribute'] = 'some-value';
58	 * });
59	 * ```
60	 *
61	 * @param opts The options for the span.
62	 * @param fn The function to run in the span.
63	 * @returns The result of the function.
64	 */
65	export async function runInDevTraceSpan<R>(
66	  opts: SpanOptions & { operation: GeminiCliOperation; noAutoEnd?: boolean },
67	  fn: ({
68	    metadata,
69	  }: {
70	    metadata: SpanMetadata;
71	    endSpan: () => void;
72	  }) => Promise<R>,
73	): Promise<R> {
74	  const { operation, noAutoEnd, ...restOfSpanOpts } = opts;
75	
76	  const tracer = trace.getTracer(TRACER_NAME, TRACER_VERSION);
77	  return tracer.startActiveSpan(operation, restOfSpanOpts, async (span) => {
78	    const meta: SpanMetadata = {
79	      name: operation,
80	      attributes: {
81	        [GEN_AI_OPERATION_NAME]: operation,
82	        [GEN_AI_AGENT_NAME]: SERVICE_NAME,
83	        [GEN_AI_AGENT_DESCRIPTION]: SERVICE_DESCRIPTION,
84	        [GEN_AI_CONVERSATION_ID]: sessionId,
85	      },
86	    };
87	    const endSpan = () => {
88	      try {
89	        if (meta.input !== undefined) {
90	          span.setAttribute(
91	            GEN_AI_INPUT_MESSAGES,
92	            safeJsonStringify(meta.input),
93	          );
94	        }
95	        if (meta.output !== undefined) {
96	          span.setAttribute(
97	            GEN_AI_OUTPUT_MESSAGES,
98	            safeJsonStringify(meta.output),
99	          );
100	        }
101	        for (const [key, value] of Object.entries(meta.attributes)) {
102	          span.setAttribute(key, value);
103	        }
104	        if (meta.error) {
105	          span.setStatus({
106	            code: SpanStatusCode.ERROR,
107	            message: getErrorMessage(meta.error),
108	          });
109	          if (meta.error instanceof Error) {
110	            span.recordException(meta.error);
111	          }
112	        } else {
113	          span.setStatus({ code: SpanStatusCode.OK });
114	        }
115	      } catch (e) {
116	        // Log the error but don't rethrow, to ensure span.end() is called.
117	        diag.error('Error setting span attributes in endSpan', e);
118	        span.setStatus({
119	          code: SpanStatusCode.ERROR,
120	          message: `Error in endSpan: ${getErrorMessage(e)}`,
121	        });
122	      } finally {
123	        span.end();
124	      }
125	    };
126	    try {
127	      return await fn({ metadata: meta, endSpan });
128	    } catch (e) {
129	      meta.error = e;
130	      if (noAutoEnd) {
131	        // For streaming operations, the delegated endSpan call will not be reached
132	        // on an exception, so we must end the span here to prevent a leak.
133	        endSpan();
134	      }
135	      throw e;
136	    } finally {
137	      if (!noAutoEnd) {
138	        // For non-streaming operations, this ensures the span is always closed,
139	        // and if an error occurred, it will be recorded correctly by endSpan.
140	        endSpan();
141	      }
142	    }
143	  });
144	}
145	
146	/**
147	 * Gets the error message from an error object.
148	 *
149	 * @param e The error object.
150	 * @returns The error message.
151	 */
152	function getErrorMessage(e: unknown): string {
153	  if (e instanceof Error) {
154	    return e.message;
155	  }
156	  if (typeof e === 'string') {
157	    return e;
158	  }
159	  return safeJsonStringify(e);
160	}
