7	import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
8	import { trace, SpanStatusCode, diag, type Tracer } from '@opentelemetry/api';
9	import { runInDevTraceSpan } from './trace.js';
10	import {
11	  GeminiCliOperation,
12	  GEN_AI_CONVERSATION_ID,
13	  GEN_AI_AGENT_DESCRIPTION,
14	  GEN_AI_AGENT_NAME,
15	  GEN_AI_INPUT_MESSAGES,
16	  GEN_AI_OPERATION_NAME,
17	  GEN_AI_OUTPUT_MESSAGES,
18	  SERVICE_DESCRIPTION,
19	  SERVICE_NAME,
20	} from './constants.js';
21	
22	vi.mock('@opentelemetry/api', async (importOriginal) => {
23	  const original = await importOriginal<typeof import('@opentelemetry/api')>();
24	  return {
25	    ...original,
26	    trace: {
27	      getTracer: vi.fn(),
28	    },
29	    diag: {
30	      error: vi.fn(),
31	    },
32	  };
33	});
34	
35	vi.mock('../utils/session.js', () => ({
36	  sessionId: 'test-session-id',
37	}));
38	
39	describe('runInDevTraceSpan', () => {
40	  const mockSpan = {
41	    setAttribute: vi.fn(),
42	    setStatus: vi.fn(),
43	    recordException: vi.fn(),
44	    end: vi.fn(),
45	  };
46	
47	  const mockTracer = {
48	    startActiveSpan: vi.fn((name, options, callback) => callback(mockSpan)),
49	  } as unknown as Tracer;
50	
51	  beforeEach(() => {
52	    vi.clearAllMocks();
53	    vi.mocked(trace.getTracer).mockReturnValue(mockTracer);
54	  });
55	
56	  afterEach(() => {
57	    vi.unstubAllEnvs();
58	  });
59	
60	  it('should start an active span', async () => {
61	    const fn = vi.fn(async () => 'result');
62	
63	    const result = await runInDevTraceSpan(
64	      { operation: GeminiCliOperation.LLMCall },
65	      fn,
66	    );
67	
68	    expect(result).toBe('result');
69	    expect(trace.getTracer).toHaveBeenCalled();
70	    expect(mockTracer.startActiveSpan).toHaveBeenCalledWith(
71	      GeminiCliOperation.LLMCall,
72	      {},
73	      expect.any(Function),
74	    );
75	  });
76	
77	  it('should set default attributes on the span metadata', async () => {
78	    await runInDevTraceSpan(
79	      { operation: GeminiCliOperation.LLMCall },
80	      async ({ metadata }) => {
81	        expect(metadata.attributes[GEN_AI_OPERATION_NAME]).toBe(
82	          GeminiCliOperation.LLMCall,
83	        );
84	        expect(metadata.attributes[GEN_AI_AGENT_NAME]).toBe(SERVICE_NAME);
85	        expect(metadata.attributes[GEN_AI_AGENT_DESCRIPTION]).toBe(
86	          SERVICE_DESCRIPTION,
87	        );
88	        expect(metadata.attributes[GEN_AI_CONVERSATION_ID]).toBe(
89	          'test-session-id',
90	        );
91	      },
92	    );
93	  });
94	
95	  it('should set span attributes from metadata on completion', async () => {
96	    await runInDevTraceSpan(
97	      { operation: GeminiCliOperation.LLMCall },
98	      async ({ metadata }) => {
99	        metadata.input = { query: 'hello' };
100	        metadata.output = { response: 'world' };
101	        metadata.attributes['custom.attr'] = 'value';
102	      },
103	    );
104	
105	    expect(mockSpan.setAttribute).toHaveBeenCalledWith(
106	      GEN_AI_INPUT_MESSAGES,
107	      JSON.stringify({ query: 'hello' }),
108	    );
109	    expect(mockSpan.setAttribute).toHaveBeenCalledWith(
110	      GEN_AI_OUTPUT_MESSAGES,
111	      JSON.stringify({ response: 'world' }),
112	    );
113	    expect(mockSpan.setAttribute).toHaveBeenCalledWith('custom.attr', 'value');
114	    expect(mockSpan.setStatus).toHaveBeenCalledWith({
115	      code: SpanStatusCode.OK,
116	    });
117	    expect(mockSpan.end).toHaveBeenCalled();
118	  });
119	
120	  it('should handle errors in the wrapped function', async () => {
121	    const error = new Error('test error');
122	    await expect(
123	      runInDevTraceSpan({ operation: GeminiCliOperation.LLMCall }, async () => {
124	        throw error;
125	      }),
126	    ).rejects.toThrow(error);
127	
128	    expect(mockSpan.setStatus).toHaveBeenCalledWith({
129	      code: SpanStatusCode.ERROR,
130	      message: 'test error',
131	    });
132	    expect(mockSpan.recordException).toHaveBeenCalledWith(error);
133	    expect(mockSpan.end).toHaveBeenCalled();
134	  });
135	
136	  it('should respect noAutoEnd option', async () => {
137	    let capturedEndSpan: () => void = () => {};
138	    const result = await runInDevTraceSpan(
139	      { operation: GeminiCliOperation.LLMCall, noAutoEnd: true },
140	      async ({ endSpan }) => {
141	        capturedEndSpan = endSpan;
142	        return 'streaming';
143	      },
144	    );
145	
146	    expect(result).toBe('streaming');
147	    expect(mockSpan.end).not.toHaveBeenCalled();
148	
149	    capturedEndSpan();
150	    expect(mockSpan.end).toHaveBeenCalled();
151	  });
152	
153	  it('should automatically end span on error even if noAutoEnd is true', async () => {
154	    const error = new Error('streaming error');
155	    await expect(
156	      runInDevTraceSpan(
157	        { operation: GeminiCliOperation.LLMCall, noAutoEnd: true },
158	        async () => {
159	          throw error;
160	        },
161	      ),
162	    ).rejects.toThrow(error);
163	
164	    expect(mockSpan.end).toHaveBeenCalled();
165	  });
166	
167	  it('should handle exceptions in endSpan gracefully', async () => {
168	    mockSpan.setAttribute.mockImplementation(() => {
169	      throw new Error('attribute error');
170	    });
171	
172	    await runInDevTraceSpan(
173	      { operation: GeminiCliOperation.LLMCall },
174	      async ({ metadata }) => {
175	        metadata.input = 'trigger error';
176	      },
177	    );
178	
179	    expect(diag.error).toHaveBeenCalled();
180	    expect(mockSpan.setStatus).toHaveBeenCalledWith(
181	      expect.objectContaining({
182	        code: SpanStatusCode.ERROR,
183	        message: expect.stringContaining('attribute error'),
184	      }),
185	    );
186	    expect(mockSpan.end).toHaveBeenCalled();
187	  });
188	});
