84	  // This regex matches a "Grapheme Cluster" manually:
85	  // 1. A surrogate pair OR a single character...
86	  // 2. Followed by any number of "Combining Marks" (\p{M})
87	  // 'u' flag is required for Unicode property escapes
88	  const graphemeRegex = /(?:[\uD800-\uDBFF][\uDC00-\uDFFF]|.)\p{M}*/gu;
89	
90	  let truncatedStr = '';
91	  let match: RegExpExecArray | null;
92	
93	  while ((match = graphemeRegex.exec(str)) !== null) {
94	    const segment = match[0];
95	
96	    // If adding the whole cluster (base char + accent) exceeds maxLength, stop.
97	    if (truncatedStr.length + segment.length > maxLength) {
98	      break;
99	    }
100	
101	    truncatedStr += segment;
102	    if (truncatedStr.length >= maxLength) break;
103	  }
104	
105	  // Final safety check for dangling high surrogates
106	  if (truncatedStr.length > 0) {
107	    const lastCode = truncatedStr.charCodeAt(truncatedStr.length - 1);
108	    if (lastCode >= 0xd800 && lastCode <= 0xdbff) {
109	      truncatedStr = truncatedStr.slice(0, -1);
110	    }
111	  }
112	
113	  return truncatedStr + suffix;
